INSERT INTO  novels  ( novel_id ,  title ,  author ,  genre ,  description ,  cover_image ,  price ,  created_at ,  rating ) VALUES
(1, 'Blue Lock', 'Muneyuki Kaneshiro', 'Sports', 'A competitive football manga about talented players fighting to become the greatest striker.', 'cover1.jpg', 2.99, '2026-10-11 19:13:18', 5),
(2, 'Jujutsu Kaisen', 'Gege Akutami', 'Action', 'A young student enters the world of cursed spirits and supernatural battles.', 'cover2.jpg', 3.99, '2026-10-11 19:13:18', 0),
(3, 'Demon Slayer', 'Koyoharu Gotouge', 'Fantasy', 'A young demon slayer fights dangerous demons while searching for a way to restore his sister.', 'cover3.jpg', 2.99, '2026-10-11 19:13:18', 1),
(4, 'Chainsaw Man', 'Tatsuki Fujimoto', 'Action', 'A poor devil hunter gains incredible powers after merging with his mysterious chainsaw companion.', 'cover4.jpg', 0.00, '2026-10-11 19:13:18', 0),
(5, 'Tokyo Ghoul', 'Sui Ishida', 'Horror', 'A college student becomes half-ghoul and struggles to survive between humans and monsters.', 'cover5.jpg', 3.99, '2026-10-11 19:13:18', 0),
(6, 'Death Note', 'Tsugumi Ohba', 'Mystery', 'A student discovers a supernatural notebook capable of killing anyone whose name is written inside it.', 'cover6.jpg', 2.49, '2026-10-11 19:13:18', 2),
(7, 'One Punch Man', 'ONE', 'Action', 'A hero who can defeat almost any enemy with one punch searches for a real challenge.', 'cover7.jpg', 2.99, '2026-10-11 19:13:18', 0),
(8, 'Haikyuu!!', 'Haruichi Furudate', 'Sports', 'A short but determined volleyball player dreams of becoming a great athlete.', 'cover8.jpg', 1.99, '2026-10-11 19:13:18', 0),
(9, 'Attack on Titan', 'Hajime Isayama', 'Fantasy', 'Humanity fights for survival against gigantic creatures known as Titans.', 'cover9.jpg', 4.49, '2026-10-11 19:13:18', 0),
(10, 'My Hero Academia', 'Kohei Horikoshi', 'Superhero', 'A powerless boy dreams of becoming a professional hero in a world where superpowers are common.', 'cover10.jpg', 2.99, '2026-10-11 19:13:18', 0),
(11, 'Spy x Family', 'Tatsuya Endo', 'Comedy', 'A spy, an assassin and a telepath create a fake family while hiding their unusual secrets.', 'cover11.jpg', 2.49, '2026-10-11 19:13:18', 0),
(12, 'Tokyo Revengers', 'Ken Wakui', 'Action', 'A young man travels back in time to change the fate of people connected to a dangerous gang.', 'cover12.jpg', 3.49, '2026-10-11 19:13:18', 0),
(13, 'Dr. Stone', 'Riichiro Inagaki', 'Science Fiction', 'After humanity is mysteriously petrified, a genius teenager attempts to rebuild civilization using science.', 'cover13.jpg', 2.99, '2026-10-11 19:13:18', 0),
(14, 'Black Clover', 'Yuki Tabata', 'Fantasy', 'A magicless orphan works toward becoming the greatest magic knight in a world ruled by magic.', 'cover14.jpg', 2.99, '2026-10-11 19:13:18', 0),
(15, 'Naruto', 'Masashi Kishimoto', 'Shonen fantasy', 'Shunned by his village because of a terrifying nine-tailed fox demon sealed inside him as a baby, a loudmouthed, underdog ninja named Naruto Uzumaki trains relentlessly to win his peers\' respect and achieve his ultimate dream of becoming the Hokage—the leader of his village', 'cover15.jpg', 1.99, '2026-10-11 19:13:18', 0),
(16, 'Lord of mysteries', 'Cuttlefish That Loves Diving', 'dark fantasy', 'After transmigrating into the body of Klein Moretti in an alternate Victorian-era steampunk world, a modern young man must master ritual magic, consume supernatural potions, and pose as a god-like entity known as \"The Fool\" to fight cosmic horrors and find a way back home.', 'cover16.jpg', 4.99, '2026-10-11 19:13:18', 0),
(17, 'Omniscient Reader', 'Sing Shong', 'Fantasy', 'A reader discovers that the novel he finished reading has become reality and only he knows how the story ends.', 'cover17.jpg', 3.99, '2026-10-11 19:13:18', 0),
(18, 'Tower of God', 'SIU', 'Fantasy', 'A mysterious tower offers unimaginable rewards to those brave enough to climb it.', 'cover18.jpg', 3.49, '2026-10-11 19:13:18', 0),
(19, 'The Beginning After The End', 'TurtleMe', 'Fantasy', 'A powerful king is reincarnated into a magical world and receives another chance at life.', 'cover19.jpg', 4.49, '2026-10-11 19:13:18', 0),
(20, 'Lookism', 'Park Tae-jun', 'Drama', 'A bullied student discovers he can switch between two completely different bodies.', 'cover20.jpg', 2.99, '2026-10-11 19:13:18', 5),
(21, 'The god of high school', 'Yongje Park', 'Action', 'Martial artists from across Korea compete in a mysterious tournament with powerful supernatural secrets.', 'cover21.jpg', 3.49, '2026-10-11 19:13:18', 0),
(22, 'Spider-Man: Friendly Neighborhood', 'Marvel Comics', 'Superhero', 'Peter Parker balances everyday responsibilities with helping people as Spider-Man in New York City.', 'cover22.jpg', 2.99, '2026-10-11 19:13:18', 0),
(23, 'The Avengers', 'Marvel Comics', 'Superhero', 'Earth’s heroes unite as a team to face threats that no single hero can handle alone.', 'cover23.jpg', 3.99, '2026-10-11 19:13:18', 0),
(24, 'Iron Man', 'Marvel Comics', 'Superhero', 'Inventor Tony Stark uses advanced technology and his armored suit to protect people.', 'cover24.jpg', 3.49, '2026-10-11 19:13:18', 0),
(25, 'Captain America', 'Marvel Comics', 'Superhero', 'Steve Rogers stands for courage and teamwork while facing challenges as Captain America.', 'cover25.jpg', 4.99, '2026-10-11 19:13:18', 0),
(26, 'Thor', 'Marvel Comics', 'Fantasy Superhero', 'The thunder god adventures across realms, learning responsibility and defending those in danger.', 'cover26.jpg', 3.99, '2026-10-11 19:13:18', 0),
(27, 'Black Panther', 'Marvel Comics', 'Superhero', 'T’Challa protects Wakanda while navigating the responsibilities of leadership and heroism.', 'cover27.jpg', 2.99, '2026-10-11 19:13:18', 0),
(28, 'Ms. Marvel', 'Marvel Comics', 'Superhero', 'Kamala Khan discovers her powers and explores what it means to become a hero.', 'cover28.jpg', 2.99, '2026-10-11 19:13:18', 0),
(29, 'Fantastic Four', 'Marvel Comics', 'Science Fiction Superhero', 'A team of explorers with extraordinary abilities confronts scientific mysteries and unusual threats.', 'cover29.jpg', 2.49, '2026-10-11 19:13:18', 0),
(30, 'Spiderman', 'Stan Lee', 'Sci-fi fantasy', 'Bitten by a radioactive spider, nerdy high school student Peter Parker gains incredible arachnid-like abilities—including wall-crawling, superhuman agility, and a predictive \"spider-sense\"—which he vows to use to protect New York City after the tragic murder of his Uncle Ben teaches him that \"with great power there must also come great responsibility.\"', 'cover30.jpg', 3.49, '2026-10-11 19:13:18', 3),
(31, 'Guardians of the Galaxy', 'Marvel Comics', 'Science Fiction Superhero', 'A group of unlikely space adventurers work together to protect the galaxy.', 'cover31.jpg', 3.99, '2026-10-19 05:16:42', 1),
(32, 'Hawkeye', 'Marvel Comics', 'Superhero', 'A skilled archer and hero takes on missions that test his resourcefulness and resolve.', 'cover32.jpg', 3.49, '2026-10-19 05:16:42', 0),
(33, 'Code Geass', 'Ichirō Ōkouchi', 'Mecha', 'An exiled prince gains the power of absolute command and leads a rebellion against a vast empire.', 'cover33.jpg', 3.99, '2026-10-19 05:16:42', 0),
(34, 'Cowboy Bebop', 'Shinichirō Watanabe', 'Space Western', 'A ragtag crew of bounty hunters drifts through space chasing criminals while running from their pasts.', 'cover34.jpg', 2.99, '2026-10-19 05:16:42', 0),
(35, 'Monster', 'Naoki Urasawa', 'Psychological Thriller', 'A brilliant surgeon saves a boy who grows up to become a terrifying serial killer, forcing him to hunt him down.', 'cover35.jpg', 4.49, '2026-10-19 05:16:42', 0),
(36, 'Vagabond', 'Takehiko Inoue', 'Historical', 'A legendary swordsman seeks enlightenment and the true meaning of strength through countless duels.', 'cover36.jpg', 3.99, '2026-10-19 05:16:42', 0),
(37, '20th Century Boys', 'Naoki Urasawa', 'Mystery', 'A group of childhood friends reunite to stop a cult leader fulfilling an apocalyptic prophecy they invented as kids.', 'cover37.jpg', 4.49, '2026-10-19 05:16:42', 0),
(38, 'Bleach', 'Tite Kubo', 'Supernatural', 'A teenager gains the powers of a Soul Reaper and must protect the living from evil spirits.', 'cover38.jpg', 2.99, '2026-10-19 05:16:42', 0),
(39, 'Fairy Tail', 'Hiro Mashima', 'Fantasy', 'A rambunctious wizard guild takes on dangerous jobs while protecting each other like family.', 'cover39.jpg', 2.49, '2026-10-19 05:16:42', 0),
(40, 'Hunter x Hunter', 'Yoshihiro Togashi', 'Adventure', 'A boy sets out to become a Hunter and find his missing father in a world of deadly trials and strange powers.', 'cover40.jpg', 3.49, '2026-10-19 05:16:42', 0),
(41, 'Solo Leveling', 'Chugong', 'Action Fantasy', 'The world\'s weakest hunter gains a mysterious system that lets him level up without limit.', 'cover41.jpg', 3.99, '2026-10-19 05:16:42', 0),
(42, 'The Remarried Empress', 'Alphatart', 'Romance Fantasy', 'A betrayed empress divorces her cheating husband and remarries a powerful emperor, reshaping the empire.', 'cover42.jpg', 2.99, '2026-10-19 05:16:42', 0),
(43, 'Who Made Me a Princess', 'Plutus', 'Romance Fantasy', 'A girl reincarnated as a doomed princess must win over her cold father to survive her tragic fate.', 'cover43.jpg', 2.49, '2026-10-19 05:16:42', 0),
(44, 'Villains Are Destined to Die', 'Gwon Gyeoeul', 'Romance Fantasy', 'Trapped in a hard-mode otome game, a player must survive as the villainess and escape death flags.', 'cover44.jpg', 2.99, '2026-10-19 05:16:42', 0),
(45, 'I Shall Master This Family', 'Kim Roeg', 'Romance Fantasy', 'A reincarnated heiress uses her knowledge of the future to save her family from ruin.', 'cover45.jpg', 3.49, '2026-10-19 05:16:42', 0),
(46, '1984', 'George Orwell', 'Dystopian', 'In a totalitarian future, one man dares to rebel against a regime that controls every thought.', 'cover46.jpg', 1.99, '2026-10-19 05:16:42', 0),
(47, 'Pig pen', 'Carnby Kim', 'horror', 'Farm animals overthrow their human master only to find their new leaders just as tyrannical.', 'cover47.jpg', 1.49, '2026-10-19 05:16:42', 0),
(48, 'Brave New World', 'Aldous Huxley', 'Dystopian', 'A society engineered for pleasure and stability hides a chilling cost to human freedom.', 'cover48.jpg', 2.49, '2026-10-19 05:16:42', 0),
(49, 'Fahrenheit 451', 'Ray Bradbury', 'Dystopian', 'A fireman who burns books begins to question the world he has helped to build.', 'cover49.jpg', 2.49, '2026-10-19 05:16:42', 0),
(50, 'The Great Gatsby', 'F. Scott Fitzgerald', 'Drama', 'A mysterious millionaire pursues a lost love amid the glittering excess of the Jazz Age.', 'cover50.jpg', 1.99, '2026-10-19 05:16:42', 0),
(51, 'Pride and Prejudice', 'Jane Austen', 'Romance', 'A sharp-witted young woman navigates courtship, class, and pride in Regency England.', 'cover51.jpg', 1.49, '2026-10-19 05:16:42', 0),
(52, 'The Hobbit', 'J.R.R. Tolkien', 'Fantasy', 'A reluctant hobbit joins a company of dwarves on a quest to reclaim a mountain from a dragon.', 'cover52.jpg', 2.99, '2026-10-19 05:16:42', 0),
(53, 'Dune', 'Frank Herbert', 'Science Fiction', 'A young heir becomes entangled in a desert planet\'s deadly politics and mystical destiny.', 'cover53.jpg', 4.49, '2026-10-19 05:16:42', 0),
(54, 'Foundation', 'Isaac Asimov', 'Science Fiction', 'A mathematician predicts the fall of a galactic empire and plants seeds for its successor.', 'cover54.jpg', 3.49, '2026-10-19 05:16:42', 0),
(55, 'Ender\'s Game', 'Orson Scott Card', 'Science Fiction', 'A gifted child is trained in a war game that may determine humanity\'s survival.', 'cover55.jpg', 3.49, '2026-10-19 05:16:42', 0),
(56, 'The Name of the Wind', 'Patrick Rothfuss', 'Fantasy', 'A legendary magician recounts his rise from orphan to the most notorious wizard of his age.', 'cover56.jpg', 4.99, '2026-10-19 05:16:42', 0),
(57, 'Mistborn', 'Brandon Sanderson', 'Fantasy', 'A street thief discovers she can burn metals for magical power and joins a rebellion against an immortal tyrant.', 'cover57.jpg', 3.99, '2026-10-19 05:16:42', 0),
(58, 'The Way of Kings', 'Brandon Sanderson', 'Epic Fantasy', 'On a world of storms, ancient oaths resurface as warring factions face a renewed threat.', 'cover58.jpg', 4.99, '2026-10-19 05:16:42', 0),
(59, 'A Game of Thrones', 'George R.R. Martin', 'Epic Fantasy', 'Noble houses scheme for a throne while an ancient winter creeps toward the realm.', 'cover59.jpg', 4.99, '2026-10-19 05:16:42', 0),
(60, 'The Gunslinger', 'Stephen King', 'Dark Fantasy', 'A lone gunslinger pursues a mysterious man in black across a dying, desolate world.', 'cover60.jpg', 3.49, '2026-10-19 05:16:42', 0),
