CREATE DATABASE novel;
USE novel;

CREATE TABLE chapters (
  chapter_id int NOT NULL AUTO_INCREMENT,
  novel_id int NOT NULL,
  chapter_number int NOT NULL,
  chapter_title varchar(150) DEFAULT NULL,
  content longtext NOT NULL,
  PRIMARY KEY ( chapter_id ),
  UNIQUE KEY  unique_chapter  ( novel_id , chapter_number )
);


CREATE TABLE  novels  (
   novel_id  int NOT NULL AUTO_INCREMENT,
   title  varchar(150) NOT NULL,
   author  varchar(100) NOT NULL,
   genre  varchar(100) NOT NULL,
   description  text,
   cover_image  varchar(255) DEFAULT 'default.png',
   price  decimal(8,2) NOT NULL DEFAULT '0.00',
   created_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP,
   rating  tinyint NOT NULL DEFAULT '1',
  PRIMARY KEY ( novel_id )
);

CREATE TABLE  novel_ratings  (
   rating_id  int NOT NULL AUTO_INCREMENT,
   user_id  int NOT NULL,
   novel_id  int NOT NULL,
   rating  tinyint NOT NULL,
   review  text,
   created_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP,
   updated_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ( rating_id ),
  UNIQUE KEY  unique_user_novel_rating  ( user_id , novel_id ),
  KEY  novel_id  ( novel_id )
) ;


CREATE TABLE  payments  (
   payment_id  int NOT NULL AUTO_INCREMENT,
   purchase_id  int NOT NULL,
   user_id  int NOT NULL,
   novel_id  int NOT NULL,
   amount  decimal(8,2) NOT NULL,
   payment_method  enum('UPI','CARD','NET_BANKING') NOT NULL,
   transaction_id  varchar(64) NOT NULL,
   payment_status  enum('PAID','FAILED') NOT NULL DEFAULT 'PAID',
   paid_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ( payment_id ),
  UNIQUE KEY  transaction_id  ( transaction_id ),
  KEY  purchase_id  ( purchase_id ),
  KEY  idx_payments_user  ( user_id ),
  KEY  idx_payments_novel  ( novel_id )
);


CREATE TABLE  purchases  (
   purchase_id  int NOT NULL AUTO_INCREMENT,
   user_id  int NOT NULL,
   novel_id  int NOT NULL,
   amount  decimal(8,2) NOT NULL DEFAULT '0.00',
   purchased_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ( purchase_id ),
  UNIQUE KEY  unique_purchase  ( user_id , novel_id ),
  KEY  novel_id  ( novel_id )
);


CREATE TABLE  reading_history  (
   history_id  int NOT NULL AUTO_INCREMENT,
   user_id  int NOT NULL,
   novel_id  int NOT NULL,
   chapter_id  int NOT NULL,
   last_read_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ( history_id ),
  UNIQUE KEY  unique_progress  ( user_id , novel_id ),
  KEY  novel_id  ( novel_id ),
  KEY  chapter_id  ( chapter_id )
);


CREATE TABLE  reviews  (
   review_id  int NOT NULL AUTO_INCREMENT,
   novel_id  int NOT NULL,
   user_id  int NOT NULL,
   rating  tinyint NOT NULL,
   review_text  text,
   created_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ( review_id ),
  UNIQUE KEY  one_review_per_user  ( novel_id , user_id )
) ;

CREATE TABLE  users  (
   user_id  int NOT NULL AUTO_INCREMENT,
   username  varchar(50) NOT NULL,
   email  varchar(100) NOT NULL,
   password  varchar(255) NOT NULL,
   profile_pic  varchar(255) DEFAULT NULL,
   created_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ( user_id ),
  UNIQUE KEY  username  ( username ),
  UNIQUE KEY  email  ( email )
);


CREATE TABLE  wishlist  (
   wishlist_id  int NOT NULL AUTO_INCREMENT,
   user_id  int NOT NULL,
   novel_id  int NOT NULL,
   added_at  timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ( wishlist_id ),
  UNIQUE KEY  unique_wish  ( user_id , novel_id ),
  KEY  novel_id  ( novel_id )
);



ALTER TABLE  chapters 
  ADD CONSTRAINT  chapters_ibfk_1  FOREIGN KEY ( novel_id ) REFERENCES  novels  ( novel_id ) ON DELETE CASCADE;

ALTER TABLE  payments 
  ADD CONSTRAINT  payments_ibfk_1  FOREIGN KEY ( purchase_id ) REFERENCES  purchases  ( purchase_id ) ON DELETE CASCADE,
  ADD CONSTRAINT  payments_ibfk_2  FOREIGN KEY ( user_id ) REFERENCES  users  ( user_id ) ON DELETE CASCADE,
  ADD CONSTRAINT  payments_ibfk_3  FOREIGN KEY ( novel_id ) REFERENCES  novels  ( novel_id ) ON DELETE CASCADE;

ALTER TABLE  purchases 
  ADD CONSTRAINT  purchases_ibfk_1  FOREIGN KEY ( user_id ) REFERENCES  users  ( user_id ) ON DELETE CASCADE,
  ADD CONSTRAINT  purchases_ibfk_2  FOREIGN KEY ( novel_id ) REFERENCES  novels  ( novel_id ) ON DELETE CASCADE;

ALTER TABLE  reading_history 
  ADD CONSTRAINT  reading_history_ibfk_1  FOREIGN KEY ( user_id ) REFERENCES  users  ( user_id ) ON DELETE CASCADE,
  ADD CONSTRAINT  reading_history_ibfk_2  FOREIGN KEY ( novel_id ) REFERENCES  novels  ( novel_id ) ON DELETE CASCADE,
  ADD CONSTRAINT  reading_history_ibfk_3  FOREIGN KEY ( chapter_id ) REFERENCES  chapters  ( chapter_id ) ON DELETE CASCADE;

ALTER TABLE  wishlist 
  ADD CONSTRAINT  wishlist_ibfk_1  FOREIGN KEY ( user_id ) REFERENCES  users  ( user_id ) ON DELETE CASCADE,
  ADD CONSTRAINT  wishlist_ibfk_2  FOREIGN KEY ( novel_id ) REFERENCES  novels  ( novel_id ) ON DELETE CASCADE;
COMMIT;